import{_ as s,o as t,c as i,a4 as a}from"./chunks/framework.kn7HWrZO.js";const k=JSON.parse('{"title":"开发指南","description":"","frontmatter":{"editSource":"docs/development.zh.md","rawMarkdownPath":"reference/development.md"},"headers":[],"relativePath":"reference/development.md","filePath":"reference/development.md"}'),o={name:"reference/development.md"};function d(n,e,c,p,r,l){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="开发指南" tabindex="-1">开发指南 <a class="header-anchor" href="#开发指南" aria-label="Permalink to &quot;开发指南&quot;">​</a></h1><p>搭建教程引导新贡献者从准备前置条件开始，直到检出目录通过检查。后面的贡献者参考介绍仓库布局、日常工作流和 CI 组织方式。设计依据与实现细节属于链接的 Agent Note 和脚本。</p><p><a id="setup-tutorial"></a></p><h2 id="搭建教程" tabindex="-1">搭建教程 <a class="header-anchor" href="#搭建教程" aria-label="Permalink to &quot;搭建教程&quot;">​</a></h2><h3 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h3><ul><li>Node.js 要求 24.9 或更高版本。CI 覆盖 24.9、最新的 24 和 26；见 <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/.agents/notes/implemented/process/2026-10-15-node-24-runtime-floor.zh.md" target="_blank" rel="noreferrer">Node 引擎下限 Agent Note</a>。</li><li>启用 Node.js TypeScript 类型剥离。仓库构建脚本用 tsdown 的 native 配置加载器加载 <code>tsdown.config.ts</code>，因此当 <code>NODE_OPTIONS</code> 含 <code>--no-experimental-strip-types</code> 或 Node.js 构建缺少 TypeScript 支持时会失败；<code>pnpm run build</code> 会先检查这一条件并指出原因。</li><li>启用了 Corepack 的 pnpm。仓库在 <code>package.json</code> 中固定使用 <code>pnpm@11.28.5</code>；如果 <code>pnpm --version</code> 无法通过 Corepack 解析，请先运行 <code>corepack enable</code>。</li><li>Git 2.26 或更高版本；钩子设置会启用 Git 的 worktree 专属配置扩展。</li><li>可选：一个 DeepSeek API key，用于 Web、headless 和 ACP（Agent Client Protocol）自动化 agent（智能体）演示以及真实 API 的 e2e 测试。</li></ul><h3 id="windows-与-wsl-2" tabindex="-1">Windows 与 WSL 2 <a class="header-anchor" href="#windows-与-wsl-2" aria-label="Permalink to &quot;Windows 与 WSL 2&quot;">​</a></h3><p>在 Windows 上，可以使用原生工具开发，也可以通过 WSL 2 使用 Linux 环境。WSL 2 既可用于验证 Linux 行为，也可在原生依赖编译或文件系统权限阻碍 Windows 开发时提供使用 Linux 工具链的途径。每种环境都需要准备相应的运行时、编译工具和权限；WSL 是可选项。</p><p>将检出目录、已安装的依赖和工具链放在同一操作系统环境中。使用 WSL 2 时，将检出目录放在 Linux 文件系统中；使用 Windows 原生工具时，则使用 Windows 文件系统。跨两种文件系统访问会给 Git、依赖安装和构建等 I/O 密集型操作增加开销。参见微软的<a href="https://learn.microsoft.com/en-us/windows/wsl/filesystems#file-storage-and-performance-across-file-systems" target="_blank" rel="noreferrer">文件存储与性能指南</a>。</p><p>在每种环境中分别安装依赖，因为不同操作系统使用的原生二进制和链接可能不同。测试结果适用于执行测试的环境；Windows 特有行为仍需在原生 Windows 上验证。</p><h3 id="首次搭建" tabindex="-1">首次搭建 <a class="header-anchor" href="#首次搭建" aria-label="Permalink to &quot;首次搭建&quot;">​</a></h3><p>pnpm 使用严格的符号链接布局，让未声明的依赖直接失败，而不是依赖提升。依赖的构建脚本必须明确列入 <code>pnpm-workspace.yaml</code> 的允许列表。</p><p>在仓库根目录安装依赖：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p>安装过程还会通过 <code>scripts/install-lefthook.mjs</code> 配置 worktree 本地的 Lefthook 钩子。<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/.agents/notes/implemented/process/2026-07-27-worktree-local-lefthook.zh.md" target="_blank" rel="noreferrer">worktree 本地钩子 Agent Note</a> 负责钩子路径的安全约定。</p><p><a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/packages/experimental/inspector/README.zh.md#use-this-package" target="_blank" rel="noreferrer">DevTools 前端</a>通过固定版本的 npm 源码包和 Vite 在本地编译。依赖安装完成后，构建不需要网络连接或安装浏览器。workspace 与发布包的安装过程都不运行 DevTools 资源下载 hook；发布的 Inspector 包包含已构建的前端。</p><p>如果依赖是从缓存恢复或 <code>postinstall</code> 被跳过而导致钩子缺失，请手动安装：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/install-lefthook.mjs</span></span></code></pre></div><p>如果包装脚本拒绝现有 Git 配置或报告陈旧锁，请遵循其诊断和所链接的 Agent Note，不要凭猜测编辑 worktree 元数据。移动检出目录后，请重新运行包装脚本以重新生成自有路径。</p><p>新克隆后请先运行一次类型检查：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span></span></code></pre></div><p><code>pnpm run typecheck</code> 成功退出即表示搭建完成。</p><h2 id="贡献者参考" tabindex="-1">贡献者参考 <a class="header-anchor" href="#贡献者参考" aria-label="Permalink to &quot;贡献者参考&quot;">​</a></h2><p><a id="typescript-project-layout"></a></p><h3 id="typescript-项目布局" tabindex="-1">TypeScript 项目布局 <a class="header-anchor" href="#typescript-项目布局" aria-label="Permalink to &quot;TypeScript 项目布局&quot;">​</a></h3><p>仓库使用相互隔离的 Host 与 Client aggregate。普通包只登记进其中一个 aggregate；Host 包进入 <code>tsconfig.host.json</code>，Client 包进入 <code>tsconfig.client.json</code>；<code>host/webserver</code>、<code>compaction/compaction</code> 与 <code>typert/registry</code> 三个包被两个 aggregate 同时引用，作为共享 leaf，让两侧对同一份源码做类型检查。</p><table tabindex="0"><thead><tr><th>文件</th><th>角色</th><th>是否构成 program？</th></tr></thead><tbody><tr><td><code>tsconfig.json</code></td><td>solution 根：<code>extends</code> base、<code>files: []</code>、引用两个 aggregate。它是 tsserver 发现入口，也是显式执行整张 Project Reference 图时的入口；经继承的 <code>paths</code> 充当 tsx 运行 <code>scripts/</code> 时的解析配置。</td><td>否</td></tr><tr><td><code>tsconfig.host.json</code></td><td>Host aggregate：Host 包、示例、测试、脚本和 website，以及 <code>api/remotes</code> 的 Host 特例 project。</td><td>是</td></tr><tr><td><code>tsconfig.client.json</code></td><td>Client aggregate：<code>packages/client/*</code> 包及其测试、<code>apps/web</code>，以及 <code>api/remotes</code> 的 Client 特例 project。</td><td>是</td></tr><tr><td><code>tsconfig.base.json</code></td><td>共享 compilerOptions 与源码 <code>paths</code> 映射。同时是各 vitest 配置让 vite-tsconfig-paths 指向的解析门面：它没有 <code>include</code>，因此其 <code>paths</code> 适用于任何 importer。</td><td>否</td></tr><tr><td><code>tsconfig.base.client.json</code></td><td>浏览器编译设置（<code>jsx</code>、DOM lib、<code>types: []</code>），由 Client aggregate 和每个 <code>packages/client/*</code> 包 extends。</td><td>否</td></tr></tbody></table><p>Host 和 Client aggregate 类型检查为 Node 老生代堆设置 8 GiB 上限。这是单个编译进程的上限；并发构建步骤还需要额外内存。<code>pnpm run build:official --serial</code> 阻止构建步骤重叠，即使设置了 <code>DSH_GATE_CONCURRENCY</code> 也不例外；DSH 发布 workflow 使用此选项。</p><p>Host 与 Client 保持两个 aggregate program，是因为两侧在相同键下以不同服务对 cordis <code>Context</code> 接口做声明合并；单一 program 同时看到两份合并会报冲突。这种冲突只存在于 <code>ts.Program</code> 内部——模块解析永远不会触发它——所以 solution 可以同时引用两个 aggregate，一个 paths 门面也可以横跨两侧。由此推出三条纪律：</p><ul><li><code>tsconfig.base.json</code> 永不添加 <code>include</code> 或 <code>files</code>：它们会泄漏进每个 extends 它的包项目，并收窄门面的全匹配范围。</li><li>构造全仓 <code>ts.Program</code> 的脚本显式以 <code>tsconfig.host.json</code> 或 <code>tsconfig.client.json</code> 为种子——根 solution 永不作为种子，因为把两个 aggregate 展平进一个 program 会撞上 <code>Context</code> 合并冲突。</li><li>新包只登记进一个 aggregate；只有上述拆分包同时携带两个 leaf 配置，共享 leaf 因两侧需要对同一份源码做类型检查而登记进两个 aggregate。包同时具有 Node loader 入口和 browser 入口并不构成拆分理由；普通 Client 插件的两份运行时产物都在 Client 构建阶段生成。</li></ul><p>拆分 Host/Client tsconfig 的包有七个：<code>api/remotes</code>、<code>api/gateway</code>、<code>api/session-controller</code>、<code>api/workspace-controller</code>、<code>client/connection</code>、<code>session-query/session-log-export</code> 与 <code>experimental/liveshare-protocol</code>。<code>api/remotes</code> 的 Host 入口进入 Host Typert 图，而 Client 入口导入生成的 <code>/remote</code> 声明；<code>session-log-export</code> 则让 Node archive 生产代码不进入浏览器 controller；<code>liveshare-protocol</code> 把 Node 线路编解码放在 Host leaf、浏览器查看页载体放在 Client leaf。每个拆分包根 <code>tsconfig.json</code> 因此只作为 solution，两个 aggregate 和直接消费方分别引用 <code>tsconfig.host.json</code> 或 <code>tsconfig.client.json</code>。workspace <code>constraints</code> 门禁遍历可达的 Project Reference 图，并按各引用 project 自身的 compiler face 检查：只有单一配置的目标可由任一 face 引用，拆分配置的目标则必须引用匹配的 leaf，不得引用 solution 根或另一侧 leaf；该门禁按「两个 leaf 配置同时存在」自动发现拆分包，所以新拆分的包会自动纳入管辖。<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/packages/api/remotes/README.zh.md" target="_blank" rel="noreferrer"><code>api-remotes</code> README</a> 与 <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/packages/session-query/session-log-export/README.zh.md" target="_blank" rel="noreferrer"><code>session-log-export</code> README</a>分别说明其拆分。</p><p><code>pnpm run build:artifacts</code> 产出全部产物，只检查并编译各 compiler face 的包 reference。Client 编译等待 Host 和 Desktop 的 bundle 完成：拆分 compiler face 会重写这些 bundle 步骤读取的共享 <code>lib/types</code> 文件。Client bundle 在 Client 编译后执行。产物步骤顺序为：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:native-system</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/generate-typert.ts</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tsc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">tsconfig.host.json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reference</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">s</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tsdown</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env.DSH_BUILD_FACE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> host</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @deepseek-ai/dsh-desktop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bundle</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tsc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">tsconfig.client.json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reference</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">s</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tsdown</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env.DSH_BUILD_FACE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> client</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:web</span></span></code></pre></div><p><code>pnpm run build:check</code> 只并发运行 <code>tsc -p tsconfig.host.json</code> 与 <code>tsc -p tsconfig.client.json</code>。project mode 依据磁盘上已有的包声明检查各 aggregate 的仓库级测试和脚本 program，从不编译 reference，因此 <code>build:check</code> 既不检测也不重建缺失或过期的 <code>build:artifacts</code> 产物；产物缺失时表现为编译器错误。<code>pnpm run build</code> 把两组步骤作为一张<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/scripts/run-gates.ts" target="_blank" rel="noreferrer">调度</a>依赖图运行：每个 aggregate 检查在本 face 的包编译完成后立即开始，与其余产物步骤重叠执行。三个命令中，<code>DSH_GATE_CONCURRENCY</code> 限制并发步骤数（<code>1</code> 按依赖顺序执行），<code>DSH_GATE_FAIL_FAST=1</code> 在第一个失败时停止其余步骤；否则失败只跳过其依赖方，因此会报告所有相互独立的错误。失败步骤打印自身输出，任一失败都以非零状态退出且不写 client build record。 Host TypeScript 编译进程的 V8 old-space 上限为 8 GiB，用于包依赖图和无缓存的 aggregate 检查。</p><p>按改动需要选择命令：</p><table tabindex="0"><thead><tr><th>场景</th><th>命令</th></tr></thead><tbody><tr><td>迭代包源码并需要可运行的产物</td><td><code>pnpm run build:artifacts</code>；<code>dev:web</code> 与 <code>dev:desktop</code> 启动前会先执行它</td></tr><tr><td>检查测试、脚本、benchmarks 或 website 代码的类型</td><td>在最近一次 <code>build:artifacts</code> 之后运行 <code>pnpm run build:check</code>；包源码有改动时先重新运行 <code>build:artifacts</code></td></tr><tr><td>声明 TypeScript 工作完成之前</td><td>在最近一次 <code>build:artifacts</code> 之后运行 <code>pnpm run build:check</code>，或运行 <code>pnpm run build</code></td></tr><tr><td>完整验证（与 CI 必需的构建 lane 相同）</td><td><code>pnpm run build</code></td></tr><tr><td>只做类型检查、不需要 Web 与 Desktop 产物</td><td><code>pnpm run typecheck</code></td></tr><tr><td>lint 或文档代码块检查</td><td><code>pnpm run lint</code> 或 <code>pnpm run doc-typecheck</code>；它们各自先准备 <code>host-contracts</code></td></tr></tbody></table><p>PR 产物 builder 运行 <code>build:artifacts</code>；必需的 Linux 与 Windows 普通构建以及公开 <code>typecheck</code> 还检查仓库级测试和脚本 program。CI benchmark 准备阶段还对其临时 library 输出使用 <code>--noCheck</code>，由这些必需构建负责诊断；其他产物 builder 保留包检查（<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/.agents/notes/implemented/process/2026-10-05-pr-artifact-typechecks.zh.md" target="_blank" rel="noreferrer">理由</a>）。</p><p>两次 tsdown 都匹配 <code>vendor/*</code>、<code>packages/*/*</code> 与 <code>apps/cli</code>，Host 阶段另外匹配 <code>apps/desktop-host</code>；两者都不扫描构建产物来发现 Client 包，也不维护 Host/Client 包过滤表。包内 tsdown 配置根据 <code>DSH_BUILD_FACE</code> 决定当前阶段的入口：普通 Client 插件在 Client 阶段同时生成 Node loader 与 browser bundle；<code>api-remotes</code> 通过 <code>hostPhase: true</code> 提前生成 Host 入口，再在 Client 阶段只生成 browser bundle。tsdown 只消费 <code>lib/types</code> 中由前置 tsc 发射的 JavaScript。tsdown 并发构建匹配到的 workspace 成员；<code>apps/desktop</code> 的主进程 bundle 需要从工作区 devDependencies 的 <code>lib/</code> 产物内联这些包，因此在 Host 阶段之后单独一步打 bundle（<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/apps/desktop/README.zh.md#bundled-workspace-dependencies" target="_blank" rel="noreferrer">Desktop README</a>）。</p><p>Typert 通过 <code>tsconfig.host.json</code> 分析 Host 类型，在包编译之前生成 Host 反射和 Host-for-Client Remote 声明。仅源码的 <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/scripts/generate-typert.ts" target="_blank" rel="noreferrer"><code>generate-typert.ts</code></a> 阶段拒绝依赖构建产物的工作区导入，包括经由依赖回到生成声明的元数据依赖。Host tsdown 转换源码装饰器，但不重复生成元数据；Client tsdown 同样使用已有元数据。<code>pnpm run typecheck</code> 生成元数据，按 reference 顺序编译 Host 与 Client 包，并在每个 aggregate 的包编译完成后以 <code>tsc -b</code> 检查它。该命令跳过 native addon、bundle、Web 和 client build record。<code>lint</code>、<code>lint:fix</code> 与 <code>doc-typecheck</code> 通过 <code>compile-referenced-projects.ts host-contracts</code> 准备元数据与 Host 包声明；生成失败时不启动依赖它的编译。这些仅生成声明的命令不更新运行时 bundle；启动或测试构建产物之前应运行 <code>build:artifacts</code>。</p><p><code>pnpm run build</code> 与 <code>build:artifacts</code> 会内联根包版本、七位源码 commit，并在 Git 报告本地变化时内联 dirty 标记；调用方提供的其他 <code>DSH_CLIENT_*</code> 值也会被继承。<code>pnpm run build:official</code> 是与 CI 和 release 产物构建等价的跨平台本地命令，并省略本地 dirty 标记。每次 <code>build</code> 或 <code>build:artifacts</code> 成功后都会写入一份被 gitignore 的记录，把精确公开值与 Vite 输出及动态 client bundle 绑定；release 打包和 built Web 测试会拒绝缺少记录或被后续局部构建改动的产物。<code>pnpm run dev:web</code> 会先执行 <code>build:artifacts</code>（<code>--skip-build</code> 则复用现有产物树），再读取一次当前版本和 Git 状态，并在本次会话的所有 watcher stage 之间共享该环境；它不会校验完整构建记录，因为 watcher stage 会重写记录覆盖的产物。</p><p><code>pnpm run build --profile local</code> 显式选择本地客户端品牌，保留仓库版本、commit 与 dirty 元数据，并丢弃继承的客户端标题及其他公开覆盖值。<code>build:official</code> 保留其精确的官方值。<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/apps/desktop/packaging/README.zh.md#configuration-and-local-builds" target="_blank" rel="noreferrer">Desktop 打包</a> 按签名模式选择 profile。</p><p>静态分析和测试通过 base 的 <code>paths</code> 映射把工作区 import 解析到 <code>src</code>，且必须在干净树上通过；消费构建产物 <code>lib/</code> 的门禁显式声明该依赖。生成的 Host-for-Client Remote 声明是有意设置的例外：公共 <code>typecheck</code>、<code>lint</code> 和 <code>doc-typecheck</code> 命令会先生成这些声明，而内部 <code>*:contracts-ready</code> 脚本假定调用它的公共命令或调度器门禁已经依赖 Typert 约定生成阶段或完整构建。门禁准备约定见 <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/.agents/notes/implemented/architecture/2026-08-02-typert-remote-method-calls.zh.md" target="_blank" rel="noreferrer">Typert Remote Agent Note</a>。</p><p>业务服务在 Host 使用 <code>@Remote</code> 或 <code>@RemoteScope</code> 声明可调用方法；Host 构建生成 Host-for-Client 类型与运行时贡献，Client 的 <code>api-remotes</code> 组合加载这些贡献并挂到 <code>ctx.remote</code> 与作用域 <code>agentCtx.remote</code> namespace。两侧的生成产物、装配关系、SRC 开发回退和 Web 构建顺序见 <a href="./api-gateway.html">API Gateway</a>。</p><p>如果相关的本地检查需要使用构建后的包产物，请先构建一次：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p><code>pnpm run hygiene</code> 包含 <code>publint</code>（用构建出的 <code>lib/*.js</code> 文件校验包入口点）和 <code>verify-node-next-types</code>（用一个临时的 NodeNext 消费方校验构建出的声明文件）。新 worktree 在 <code>pnpm run build</code> 运行之前没有打包的 JS 和声明文件；普通提交和推送无需构建，除非所选检查会使用这些产物。</p><h3 id="环境变量" tabindex="-1">环境变量 <a class="header-anchor" href="#环境变量" aria-label="Permalink to &quot;环境变量&quot;">​</a></h3><p>真实的 DeepSeek 适配器和需要密钥的 agent 演示从环境变量或仓库根目录一个被 gitignore 的 <code>.env</code> 文件读取凭证：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DEEPSEEK_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sk-...</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DEEPSEEK_BASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://...</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # optional</span></span></code></pre></div><p><code>DEEPSEEK_BASE_URL</code> 可选，默认为公开 API。请勿提交真实凭证。未设置 <code>DEEPSEEK_API_KEY</code> 时，真实 API 的 e2e 套件会自动跳过。</p><h3 id="git-集成" tabindex="-1">Git 集成 <a class="header-anchor" href="#git-集成" aria-label="Permalink to &quot;Git 集成&quot;">​</a></h3><p><code>.i18n.yaml</code> 记录使用 Git 默认文本合并。只有当两个分支都修改了同一标题分节中的语言特有内容时，记录才会冲突；先解决 Markdown 冲突，再重新运行 <code>pnpm run verify-translation-pairing --write &lt;pair&gt;</code>。如果 <code>pre-merge-commit</code> 拒绝原本能干净完成的合并，Git 会把完整结果留在暂存区但不创建提交；请修复失败后运行 <code>git commit</code>，或运行 <code>git merge --abort</code>。</p><p>lefthook 在 <code>lefthook.yml</code> 中配置，作为快速的本地检查点：</p><ul><li><code>pre-commit</code> 对照暂存的配对文档 blob 校验暂存的配对记录，使用不加载项目的 <code>.oxlintrc.staged.json</code> 配置验证暂存文件，并通过一次有界重试应用 Oxlint 修复，然后检查暂存 diff 中的空白错误，在 pi-ai 提供方元数据的输入或生成文件已暂存时校验元数据，并运行 vendor manifest（元数据清单）守卫；</li><li><code>pre-merge-commit</code> 在 Git 创建自动合并提交前执行同样以索引为准的配对检查；</li><li><code>pre-push</code> 运行 <code>pnpm run typecheck</code>；该命令先不打包地生成 Typert 约定，再运行 Client TypeScript 检查，并检查两个 aggregate。</li></ul><p>vendor manifest 守卫检查 <code>vendor/*/src</code> 下的改动是否连同对应的 <code>vendor/README.md</code> manifest 更新一起暂存。请在编辑 vendor 代码前先阅读 <code>vendor/README.md</code>。</p><p>pi-ai 检查会在内存中重新生成预期元数据。数据过期时，检查拒绝提交，不改写或暂存文件。修改 pi-ai 依赖或生成器后，请按包内的<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/packages/llm/llm-pi-ai/README.zh.md#generated-provider-metadata" target="_blank" rel="noreferrer">提供方元数据更新步骤</a>操作。</p><p>除限定范围的配对和提供方元数据检查外，这些钩子有意不运行测试、快照、文档检查、构建或 <code>hygiene</code>。贡献者只运行一次<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/AGENTS.md#run-relevant-checks-locally" target="_blank" rel="noreferrer">与改动行为相关的检查</a>；CI 负责全量覆盖率门禁、构建产物冒烟测试，以及 Node 24.9、最新的 24 和 26 兼容性矩阵。</p><p>贡献者可以选择运行 <code>pnpm run check:all</code>，执行全面的本地门禁集。该命令独立于 Git 钩子，也不是对 agent 的指令。</p><p>在 CI 之外（<code>CI</code> 不为 <code>true</code>），默认 worker 数遵循<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/scripts/parallelism.ts" target="_blank" rel="noreferrer">本地 worker 预算</a>：门禁调度器、<code>build</code>、<code>typecheck</code>、Oxlint 与 publint 为 12，Vitest fork 与本地覆盖率为 48。<code>doc-sync</code>、<code>test:docs</code>、<code>hygiene</code> 与 <code>check:all</code> 最多同时运行 8 个门禁，CI 中同样如此。<code>os.availableParallelism()</code> 报告的是宿主 CPU 数而不是容器的 CPU 配额，因此不设上限的默认值会在共享主机上超额订阅。CI 仍使用 runner 的 CPU 数。<code>DSH_GATE_CONCURRENCY</code>、<code>DSH_OXLINT_THREADS</code>、<code>DSH_COVERAGE_MAX_WORKERS</code> 与 Vitest 的 <code>--maxWorkers</code> 可覆盖这些默认值。</p><p><code>run-gates</code> 让 CLI 帮助生成器每次只运行一个子进程；直接执行 <code>pnpm run verify-cli-help</code> 时使用独立运行的 worker 预算。<code>DSH_CLI_HELP_CONCURRENCY</code> 可用正整数覆盖该子进程上限，并在启动前校验。每次调用仍使用独立的 <code>DSH_HOME</code> 与 <code>DSH_AGENTS_HOME</code>，超时限制仍为 30 秒。</p><h3 id="ci-门禁" tabindex="-1">CI 门禁 <a class="header-anchor" href="#ci-门禁" aria-label="Permalink to &quot;CI 门禁&quot;">​</a></h3><p>keyless <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/.github/workflows/ci.yml" target="_blank" rel="noreferrer">CI 工作流</a> 将独立门禁分组到若干宽粒度 lane，并在受支持的 Node 版本上运行一组较小的兼容性检查。产物消费方在各自 lane 内等待一次 build。覆盖率分区复用按平台和运行器池隔离的文件耗时，在配置的 worker 上限内均衡工作量。原生 Windows lane 运行在独立的 <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/.github/workflows/ci-windows.yml" target="_blank" rel="noreferrer">CI Windows 工作流</a>中，Python 检查运行在独立的 <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/.github/workflows/ci-python.yml" target="_blank" rel="noreferrer">CI Python 工作流</a>中，两者都可单独重新运行。必需 benchmark 在标准 GitHub 托管 Linux 上独立运行；<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/benchmarks/AGENTS.md" target="_blank" rel="noreferrer">benchmark 运行器说明</a>拥有路由及 job 超时。单独的真实 API 工作流按其配置的 worker 上限运行 <code>pnpm run test:e2e</code>。当前门禁和 job 清单以 <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/scripts/run-gates.ts" target="_blank" rel="noreferrer">scripts/run-gates.ts</a> 和工作流文件为准。</p><p>不带凭据的 dsh 依赖布局检查与 dsh/vendor 打包演练仅在 <code>DSH_CI_FAILOVER_LINUX=selfhosted</code>，且事件为受信任的 master 推送或同仓库、非 fork、非 Dependabot 拉取请求时使用现有 Linux 自托管池。其余情况（包括手动触发）均使用 <code>ubuntu-24.94</code>；手动发布仍使用托管运行器。持久化存储隔离与回退限制见<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/.agents/notes/implemented/process/2026-07-26-ci-failover-runbook.zh.md" target="_blank" rel="noreferrer">发布演练运行器说明</a>。</p><h3 id="日常命令" tabindex="-1">日常命令 <a class="header-anchor" href="#日常命令" aria-label="Permalink to &quot;日常命令&quot;">​</a></h3><p>根目录的<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/AGENTS.md#commands" target="_blank" rel="noreferrer">贡献者说明</a>概述常用命令，<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/package.json" target="_blank" rel="noreferrer"><code>package.json</code></a> 与 <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/scripts/run-gates.ts" target="_blank" rel="noreferrer">scripts/run-gates.ts</a> 则负责当前脚本和门禁清单。请选择覆盖变更表面的最小检查集。文档变更使用 <code>pnpm run doc-sync</code>；包公开行为变更还需更新所属 README 或 JSDoc，而基于构建产物的检查需要先运行 <code>pnpm run build</code>。</p><h3 id="profile-运行" tabindex="-1">Profile 运行 <a class="header-anchor" href="#profile-运行" aria-label="Permalink to &quot;Profile 运行&quot;">​</a></h3><p>从源码 checkout 运行这些演示前，请单独执行仓库构建：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>单次运行的 Headless coding agent 需要环境变量或仓库根目录 <code>.env</code> 中的 <code>DEEPSEEK_API_KEY</code>：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dsh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> headless</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;summarize this workspace&quot;</span></span></code></pre></div><p>PTC mode 演示启用代码式工具展示，并运行同一个 headless profile：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo:ptc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;summarize this workspace&quot;</span></span></code></pre></div><h3 id="应用命令" tabindex="-1">应用命令 <a class="header-anchor" href="#应用命令" aria-label="Permalink to &quot;应用命令&quot;">​</a></h3><p>Web 与 Desktop 共用同一对命令。<code>start:*</code> 启动上一次 <code>pnpm run build</code> 或 <code>build:artifacts</code> 的产物；<code>dev:*</code> 先执行 <code>build:artifacts</code> 再启动。Web 还会在源码修改时持续重建 client bundle，因为它的 Host 从源码运行，而浏览器加载的是构建产物：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start:web</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # serve built Web artifacts through the source launcher (the same launch as pnpm dsh web)</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev:web</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # build, serve, and rebuild Web client bundles on source edits</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start:desktop</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # launch built Desktop artifacts</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev:desktop</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # build, then launch Desktop</span></span></code></pre></div><p>Web 命令后面的参数会传给 <code>dsh web</code>，例如 <code>pnpm run dev:web --no-open --port 3081</code>；<code>dev:web</code> 还接受 <code>--skip-build</code> 复用现有产物树，以及 <code>--no-serve</code> 只运行重建 watcher、配合别处启动的服务器。两个 Web 命令使用正常的 Harness home，而 Desktop 命令使用 <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/apps/desktop/README.zh.md" target="_blank" rel="noreferrer">Desktop README</a> 描述的隔离开发 home。根目录 <code>Makefile</code> 以 <code>make web</code>、<code>make dev-web</code>、<code>make desktop</code>、<code>make dev-desktop</code> 和 <code>make build</code> 命名同一套命令；<code>ARGS=&#39;--no-open&#39;</code> 用于转发参数。</p><h3 id="todo-标记" tabindex="-1">TODO 标记 <a class="header-anchor" href="#todo-标记" aria-label="Permalink to &quot;TODO 标记&quot;">​</a></h3><p>请使用以下三种注释标签之一标记代码中的已知问题，按紧急程度排序：</p><ul><li><code>FIXME</code>：应当阻塞新版本发布的问题。除非评审者明确同意该更改可以合并，否则发布版本不应包含未解决的 <code>FIXME</code>；</li><li><code>TODO</code>：应当尽快修复的问题，等资源到位即可处理；</li><li><code>XXX</code>：也许某天会修复的问题，优先级最低，不作承诺。</li></ul><p>请选择与紧急程度匹配的标签，让浏览代码的人一眼分清「发布阻塞」和「有空再说」。</p><p><a id="documenting-types-verbatim-ts-type-equiv"></a></p><h3 id="逐字记录类型定义-ts-type-equiv" tabindex="-1">逐字记录类型定义（<code>ts type-equiv</code>） <a class="header-anchor" href="#逐字记录类型定义-ts-type-equiv" aria-label="Permalink to &quot;逐字记录类型定义（`ts type-equiv`）&quot;">​</a></h3><p><a href="./subsystems/">子系统</a>页面会把与源码等价的声明及其原始 JSDoc 一并粘贴，让读者看到确切类型定义和源码约定。为防止粘贴内容在源码变化时漂移，请将其围栏为 <code>```ts type-equiv</code>（而不是 <code>```ts</code>），并在 <code>scripts/type-equiv.manifest.json</code> 中登记它镜像的源文件和符号：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;doc&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;docs/subsystems/session.md&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;symbol&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;SessionEvent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;source&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;packages/core/session/src/types.ts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p><code>pnpm run verify-type-equiv</code>（<code>doc-sync</code> 的一环）随后通过 TypeScript 解析器从源码提取该符号的声明及其附带的 JSDoc，并断言代码块同时匹配两者。对于不应把实现体写进目录的类，请使用 <code>```ts public-api</code> 并设置 <code>&quot;projection&quot;: &quot;public-api&quot;</code>；门禁检查的投影会保留公共字段、构造函数、访问器、方法以及类和成员的原始 JSDoc，同时省略实现体和私有或受保护成员。比对会忽略空白和非 JSDoc 注释，但要求保留每条原始 JSDoc（包括成员文档），让读者同时看到源码约定和确切类型定义。该门禁按文档、符号和投影，在主块与 manifest 条目之间强制 1:1 对应；只有当配对 <code>.zh.md</code> 块的完整受跟踪围栏序列与其无后缀兄弟文件按字节一致且顺序相同时，才会复用后者的条目。<code>doc-typecheck</code> 对可编译围栏应用同一派生规则，同时跳过两种源码等价围栏的编译，并将其排除在 opt-out 比例的计算之外。版本目录早于根包版本的升级指南已冻结，其中的示例不参与当前 API 的编译检查。当你改动一个已记录的类型声明或其 JSDoc 时，门禁会失败直到你更新粘贴内容；当你增删一个主块时，请在同一个变更里更新 manifest。</p>',85)])])}const g=s(o,[["render",d]]);export{k as __pageData,g as default};
